INSERT INTO `chat_messages` (`id`, `conversation_id`, `sender`, `staff_id`, `message`, `read_by_staff`, `created_at`) VALUES
(1, 1, 'visitor', NULL, 'hello', 1, '2026-10-22 16:07:32'),
(2, 1, 'ai', NULL, 'Chào bạn! Mình là trợ lý AI của Viet Duc Pharmacy. Hôm nay mình có thể hỗ trợ gì cho bạn về các sản phẩm, danh mục, giá cả, hay các bài viết chăm sóc sức khỏe tại cửa hàng không ạ?', 1, '2026-10-22 16:07:44'),
(3, 1, 'visitor', NULL, 'đúng r', 1, '2026-10-22 16:08:14'),
(4, 1, 'ai', NULL, 'Dạ chào bạn! Viet Duc Pharmacy rất vui được hỗ trợ bạn hôm nay. \n\nBạn đang cần tìm mua sản phẩm nào, hay cần tư vấn về danh mục thuốc, thực phẩm chức năng, dược mỹ phẩm cũng như các bài viết chăm sóc sức khỏe của nhà thuốc không ạ?', 1, '2026-10-22 16:08:35'),
(5, 1, 'visitor', NULL, 'eeeeee', 1, '2026-10-22 16:09:44'),
(6, 1, 'staff', 4, 'hello', 1, '2026-10-22 16:10:25'),
(7, 1, 'staff', 4, 'hello ạ', 1, '2026-10-22 16:11:14'),
(8, 1, 'visitor', NULL, 'bạn tên gì vậy', 1, '2026-10-22 16:14:49'),
(9, 2, 'ai', NULL, 'Chào bạn, tại hệ thống Viet Duc Pharmacy của chúng tôi hiện có các sản phẩm thuộc danh mục hoặc liên quan đến vitamin như sau:\n\n1. **Siro ăn ngon Baby Plus**\n   - Giá hiện tại: 280.000đ (giảm từ 310.000đ)\n   - Tồn kho: Còn 20 sản phẩm\n   - Mô tả: Siro cho bé biếng ăn của công ty TNHH Medistar, sản xuất đạt tiêu chuẩn GMP.\n\n2. **Siro ăn ngon Ích Nhi Plus**\n   - Giá hiện tại: 280.000đ (giảm từ 400.000đ)\n   - Tồn kho: Còn 10 sản phẩm\n   - Đang gắn cờ Siêu deal.\n\n3. **Viên uống bổ gan tăng cường giải độc gan Dr. Liver Jpanwell (60 viên)**\n   - Giá hiện tại: 990.000đ\n   - Tồn kho: Còn 30 sản phẩm.\n\n4. **Viên uống giúp chậm quá trình lão hóa da, tăng đàn hồi da Omexxel Collagen (3 vỉ x 10 viên)**\n   - Giá hiện tại: 990đ\n   - Tồn kho: Còn 29 sản phẩm\n   - Đang gắn cờ Siêu deal.\n\n5. **Nhom4**\n   - Giá hiện tại: 200đ\n   - Tồn kho: Còn 112 sản phẩm.\n\nNgoài ra, nếu bạn quan tâm đến cách sử dụng vitamin hiệu quả (như Vitamin C), website chúng tôi có bài viết hướng dẫn chi tiết về liều dùng, thời điểm uống và các lưu ý quan trọng để tránh tác dụng phụ. \n\nBạn cần thêm thông tin chi tiết hoặc muốn được hỗ trợ đặt mua sản phẩm nào không ạ? (Lưu ý: Các thông tin về liều dùng và sản phẩm trên chỉ mang tính chất tham khảo, bạn nên tham khảo ý kiến bác sĩ hoặc dược sĩ trước khi sử dụng).', 1, '2026-10-22 16:16:05'),
(10, 3, 'staff', 1, 'hello', 1, '2026-10-22 16:20:12'),
(11, 2, 'visitor', NULL, 'svx', 1, '2026-10-22 16:20:44'),
(12, 2, 'ai', NULL, 'Chào bạn, để được dược sĩ của **Viet Duc Pharmacy** tư vấn chi tiết, bạn có thể sử dụng các chức năng gửi yêu cầu tư vấn hoặc liên hệ trực tiếp trên website. \n\nNgoài ra, nếu bạn đang gặp các vấn đề về sức khỏe, triệu chứng bệnh, hay cần hỏi về liều dùng, tác dụng phụ và cách phối hợp thuốc, các thông tin chỉ mang tính chất tham khảo. Bạn nên hỏi ý kiến trực tiếp của bác sĩ hoặc dược sĩ có chuyên môn nhé. \n\n*Lưu ý:* Nếu bạn gặp các dấu hiệu cấp cứu nguy hiểm như khó thở, đau ngực dữ dội, bất tỉnh hoặc dị ứng nặng, hãy gọi ngay cấp cứu 115 hoặc đến cơ sở y tế gần nhất ngay lập tức. \n\nBạn có muốn tra cứu thêm thông tin sản phẩm hay bài viết sức khỏe nào trên website không ạ?', 1, '2026-10-22 16:22:14'),
