(12, 'Cách Điều Trị Bệnh Trĩ Tại Nhà Không Cần Dùng Thuốc', 'Sống khỏe', NULL, '<p><span style=\"color: rgb(19, 19, 19); font-family: Roboto, Arial, sans-serif; font-size: 14px; white-space-collapse: preserve; background-color: rgba(0, 0, 0, 0.05);\">Khi bị trĩ, bạn sẽ cảm thấy khó chịu vì sự sưng đau ở vùng hậu môn. Nếu chỉ bị trĩ ở mức độ nhẹ, bạn có thể thử các cách chữa bệnh trĩ tại nhà hay cách trị bệnh trĩ tại nhà theo kinh nghiệm dân gian sau khi tham khảo ý kiến bác sĩ.</span></p>', '1773146762_OVP (2).jpg', 'https://youtu.be/-RIeDn6h8Y0?si=3wJCY7x9sJ3b6WqB', '2026-03-10 06:46:02', 'long'),
